    css='''\n<style id="torvo-category-manager-v6">\n/* TORVO CATEGORY MANAGER V6 */\n.torvoCategoryMasterRow{display:flex!important;gap:6px!important}.torvoCategoryInputWrap{position:relative;flex:1;min-width:0}.torvoCategoryInputWrap input{width:100%!important;padding-right:34px!important}.torvoCategoryDropBtn{position:absolute;right:2px;top:2px;bottom:2px;width:30px;border:0;background:#f3f6f9;color:#34465c;font-weight:900;border-radius:5px}.torvoCategoryAddBtn{background:#d71920!important;color:#fff!important;border-color:#d71920!important}.torvoCategoryDropdown{display:none;position:absolute;z-index:80;background:#fff;border:1px solid #ced8e3;border-radius:8px;box-shadow:0 8px 24px #0002;max-height:190px;overflow:auto;margin-top:4px;min-width:180px}.torvoCategoryDropdown.show{display:block}.torvoCategoryDropdown button{display:block;width:100%;border:0;border-bottom:1px solid #edf1f5;background:#fff;text-align:left;padding:9px;font-weight:700}.torvoCategoryDropdown button:hover{background:#f7f9fb}.torvoCategoryOverlay{display:none;position:fixed;inset:0;z-index:9999;background:#0008;align-items:center;justify-content:center;padding:14px}.torvoCategoryOverlay.show{display:flex}.torvoCategoryCard{width:min(430px,96vw);max-height:82vh;overflow:auto;background:#fff;border-radius:14px;padding:14px;box-shadow:0 18px 50px #0005}.torvoCategoryHead{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.torvoCategoryHead b{font-size:16px}.torvoCategoryHead button{border:0;background:#eef2f6;border-radius:50%;width:30px;height:30px;font-size:20px}.torvoCategoryAdd{display:flex;gap:6px}.torvoCategoryAdd input,.torvoCategorySearch{height:38px;border:1px solid #ced8e3;border-radius:8px;padding:8px}.torvoCategoryAdd input{flex:1;min-width:0}.torvoCategoryAdd button{border:0;border-radius:8px;background:#d71920;color:#fff;font-weight:900;padding:0 13px}.torvoCategorySearch{width:100%;margin:9px 0}.torvoCategoryMsg{min-height:18px;font-size:10px;font-weight:900}.torvoCategoryRow{display:flex;align-items:center;gap:6px;border-top:1px solid #edf1f5;padding:7px 2px}.torvoCategoryRow span{flex:1;font-weight:800}.torvoCategoryRow button{width:34px;height:30px;border:0;border-radius:7px;font-weight:900}.torvoCategoryEdit{background:#e8f1ff;color:#2368b0}.torvoCategoryDel{background:#ffe9ed;color:#d71920}\n</style>\n'''
    js='''\n<script>\nfunction torvoCategoryNames(){return Array.from(new Set([].concat(DB.categories||[],(DB.items||[]).map(function(x){return x.category})).filter(Boolean).map(U))).sort()}\nfunction torvoEnsureCategoryUI(){if(E("torvoCategoryManager"))return;var d=document.createElement("div");d.id="torvoCategoryManager";d.className="torvoCategoryOverlay";d.innerHTML='<div class="torvoCategoryCard"><div class="torvoCategoryHead"><b>MANAGE CATEGORY</b><button type="button" onclick="torvoCloseCategoryManager()">×</button></div><div class="torvoCategoryAdd"><input id="torvoCategoryNew" class="upper" placeholder="ADD CATEGORY NAME"><button type="button" onclick="torvoAddCategory()">+ ADD</button></div><div id="torvoCategoryMsg" class="torvoCategoryMsg"></div><input id="torvoCategorySearch" class="torvoCategorySearch upper" placeholder="SEARCH CATEGORY" oninput="torvoRenderCategories()"><div id="torvoCategoryRows"></div></div>';document.body.appendChild(d)}\nfunction torvoCategoryMessage(t,bad){var x=E("torvoCategoryMsg");if(x){x.textContent=t||"";x.style.color=bad?"#d71920":"#16813d"}}\nfunction torvoOpenCategoryManager(){torvoEnsureCategoryUI();E("torvoCategoryManager").classList.add("show");torvoCategoryMessage("");E("torvoCategorySearch").value="";torvoRenderCategories()}\nfunction torvoCloseCategoryManager(){var x=E("torvoCategoryManager");if(x)x.classList.remove("show")}\nfunction torvoRenderCategories(){var q=N((E("torvoCategorySearch")||{}).value||"");var rows=E("torvoCategoryRows");if(!rows)return;rows.innerHTML=torvoCategoryNames().filter(function(v){return !q||N(v).indexOf(q)>=0}).map(function(v){return '<div class="torvoCategoryRow"><span>'+H(v)+'</span><button class="torvoCategoryEdit" type="button" data-v="'+H(v)+'" onclick="torvoEditCategory(this)">✎</button><button class="torvoCategoryDel" type="button" data-v="'+H(v)+'" onclick="torvoDeleteCategory(this)">🗑</button></div>'}).join("")||'<div style="padding:10px;color:#667487">NO CATEGORY ADDED</div>'}\nfunction torvoAddCategory(){var i=E("torvoCategoryNew"),v=U((i.value||"").trim());if(!v)return torvoCategoryMessage("ENTER CATEGORY NAME",true);if(torvoCategoryNames().some(function(x){return N(x)===N(v)}))return torvoCategoryMessage("ALREADY EXISTS — "+v,true);DB.categories=DB.categories||[];DB.categories.push(v);saveDB();i.value="";if(E("pCategory"))E("pCategory").value=v;torvoCategoryMessage("✓ SUCCESSFUL — "+v+" ADDED",false);torvoRenderCategories()}\nfunction torvoEditCategory(b){var old=U(b.getAttribute("data-v")||"");var use=masterUsage("category",old);if(use>0)return torvoCategoryMessage("USED IN "+use+" RECORD(S) — CORRECT LINKED ITEM FIRST",true);var v=U((window.prompt("EDIT CATEGORY:",old)||"").trim());if(!v)return;if(torvoCategoryNames().some(function(x){return N(x)===N(v)&&N(x)!==N(old)}))return torvoCategoryMessage("ALREADY EXISTS — "+v,true);DB.categories=(DB.categories||[]).map(function(x){return N(x)===N(old)?v:x});saveDB();if(E("pCategory")&&N(E("pCategory").value)===N(old))E("pCategory").value=v;torvoCategoryMessage("✓ CATEGORY UPDATED",false);torvoRenderCategories()}\nfunction torvoDeleteCategory(b){var v=U(b.getAttribute("data-v")||"");var use=masterUsage("category",v);if(use>0)return torvoCategoryMessage("DELETE BLOCKED — USED IN "+use+" RECORD(S)",true);var code=window.prompt("ENTER DELETE CODE");if(code!=="1122")return torvoCategoryMessage("WRONG DELETE CODE",true);if(!window.confirm("DELETE "+v+" ?"))return;DB.categories=(DB.categories||[]).filter(function(x){return N(x)!==N(v)});saveDB();if(E("pCategory")&&N(E("pCategory").value)===N(v))E("pCategory").value="";torvoCategoryMessage("CATEGORY DELETED",false);torvoRenderCategories()}\nfunction torvoToggleCategoryDropdown(){var box=E("torvoCategoryDropdown");if(!box)return;var open=box.classList.toggle("show");if(!open)return;box.innerHTML=torvoCategoryNames().map(function(v){return '<button type="button" data-category="'+H(v)+'" onclick="torvoSelectCategory(this)">'+H(v)+'</button>'}).join("")||'<div style="padding:9px;color:#667487">NO CATEGORY ADDED</div>'}\nfunction torvoSelectCategory(b){if(E("pCategory"))E("pCategory").value=b.getAttribute("data-category")||"";var box=E("torvoCategoryDropdown");if(box)box.classList.remove("show")}\n</script>\n'''
    s=s.replace('</head>',css+'</head>',1)
